[16]="玄金龙子剑",
[17]="相传上古蛮族大能机缘之下，擒获玄金真龙，并取出龙魂，炼入一对子母剑中，遂得此玄金龙子剑。一旦出剑，便有金龙冲霄而起，并引动万剑震鸣，可谓威能无穷",
[18]="所有弟子攻击+{0}%\n所有弟子金行技能威力+{1}%",
[19]="所有弟子攻击+{0}<color=green>{1}</color>%\n所有弟子金行技能威力+{2}<color=green>{3}</color>%",
[20]="角仙碧玉琴",
[21]="十万大山之中，角仙一族世代守护的仙品宝物，此琴不断绽放出朵朵晶莹绚丽花卉，随清风飘荡流转。花卉所到之处，瞬息间林木丛生，百花绽放，生灵雀跃。无数年月中，此琴只存在传说中，无人识其真面目！",
[22]="所有弟子攻击+{0}%\n所有弟子木行技能威力+{1}%",
[23]="所有弟子攻击+{0}<color=green>{1}</color>%\n所有弟子木行技能威力+{2}<color=green>{3}</color>%",
[24]="云水琉璃瓶",
[25]="传闻在九天之上，云水无波，却能映照出尘世百态。而在水中央，云雾托举着一尊琉璃瓶，瓶口缓缓涌出清流落入云水中，却不激起涟漪。此等神妙之物，便是凝聚无尽水系灵力的云水琉璃瓶！",
[26]="所有弟子攻击+{0}%\n所有弟子水行技能威力+{1}%",
[27]="所有弟子攻击+{0}<color=green>{1}</color>%\n所有弟子水行技能威力+{2}<color=green>{3}</color>%",
[28]="金乌离火扇",
[29]="上古修士取金乌翎羽，并凝聚离火化作万顷火云，历经数百年，炼制成扇，此扇遍布火纹，每每挥动，火纹中便冲出一只只金乌火鸟，焚尽万物，不息不灭！",
[30]="所有弟子攻击+{0}%\n所有弟子火行技能威力+{1}%",
[31]="所有弟子攻击+{0}<color=green>{1}</color>%\n所有弟子火行技能威力+{2}<color=green>{3}</color>%",
[32]="螭虎号仙令",
[33]="螭虎乃上古时蛮荒异种，声威不在真龙之下，一声怒吼，能激荡起千万里土系灵力，使万物臣服。此宝中螭虎真魂威能更甚，一旦使出，连真仙也难伤其分毫！",
[34]="所有弟子攻击+{0}%\n所有弟子土行技能威力+{1}%",
[35]="所有弟子攻击+{0}<color=green>{1}</color>%\n所有弟子土行技能威力+{2}<color=green>{3}</color>%",
[36]="庚金混元鼎",
[37]="庚金至阳，可御百金，可辟万邪。以庚金铸鼎，百兵不侵，天雷难撼。此鼎中还蕴含着一股混元真气，可御天地金行之气，坚不可摧，亘古不灭",
[38]="所有弟子防御+{0}%\n所有弟子生命+{1}%\n所有弟子受到的金行技能伤害-{2}%",
[39]="所有弟子防御+{0}<color=green>{1}</color>%\n所有弟子生命+{2}<color=green>{3}</color>%\n所有弟子受到的金行技能伤害-{4}<color=green>{5}</color>%",
[40]="苍崖问天棋",
[41]="苍崖之巅生奇木，木力至纯，生息浓郁，得天道所钟，百年即开灵智。其花开叶落皆隐含韵律，顺应天道至理。以此木制棋，棋盘方寸之间，可观天道轮转，生生不息。",
[42]="所有弟子防御+{0}%\n所有弟子生命+{1}%\n所有弟子受到的木行技能伤害-{2}%",
[43]="所有弟子防御+{0}<color=green>{1}</color>%\n所有弟子生命+{2}<color=green>{3}</color>%\n所有弟子受到的木行技能伤害-{4}<color=green>{5}</color>%",
[44]="碧落天琼带",
[45]="天琼碧落云海间，月华神水取一瓢；清圣仙莲芳华绽，泽润天地万物荣。",
[46]="所有弟子防御+{0}%\n所有弟子生命+{1}%\n所有弟子受到的水行技能伤害-{2}%",
[47]="所有弟子防御+{0}<color=green>{1}</color>%\n所有弟子生命+{2}<color=green>{3}</color>%\n所有弟子受到的水行技能伤害-{4}<color=green>{5}</color>%",
[48]="清幽古仪灯",
[49]="仙器有灵，灯火幽幽，从何处来，往何处去？以魂火为引，仙器为罩，灯华可耀八方天地，无数生灵皆得庇佑。大道万千，灯火在前，持心守正，己身之道则明也。",
